 t jsonb; ix jsonb; d jsonb; a text; v jsonb; before_other_defaults jsonb;
 rel oid; kind text; recipient text; privileges text;
BEGIN
 IF current_setting('server_version_num')::int NOT BETWEEN 170000 AND 179999 THEN
  RAISE EXCEPTION 'correction_fixture_requires_postgresql17';
 END IF;
 IF EXISTS(SELECT 1 FROM pg_default_acl x
   WHERE x.defaclnamespace=0 OR x.defaclnamespace='public'::regnamespace) THEN
  RAISE EXCEPTION 'correction_fixture_default_acl_preexists';
 END IF;
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.oid),'[]'::jsonb)
 INTO before_other_defaults FROM pg_default_acl x;
 FOR t IN SELECT value FROM jsonb_array_elements(expected) LOOP
  rel := to_regclass('public.'||(t->>'name'));
  IF rel IS NULL OR NOT EXISTS(SELECT 1 FROM pg_class x WHERE x.oid=rel
    AND x.relkind='r' AND pg_get_userbyid(x.relowner)=t->>'owner'
    AND x.relrowsecurity AND NOT x.relforcerowsecurity AND NOT x.relispartition
    AND x.relreplident='d' AND x.reloptions IS NULL
    AND NOT EXISTS(SELECT 1 FROM pg_inherits h WHERE h.inhrelid=x.oid OR h.inhparent=x.oid)) THEN
   RAISE EXCEPTION 'correction_fixture_relation_preimage_changed' USING DETAIL=t->>'name';
  END IF;
  SELECT jsonb_agg(z::text ORDER BY z::text) INTO v FROM pg_class x CROSS JOIN LATERAL unnest(x.relacl) z
   WHERE x.oid=rel;
  IF v IS DISTINCT FROM t->'acl' THEN
   RAISE EXCEPTION 'correction_fixture_relation_acl_changed' USING DETAIL=t->>'name';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('name',x.attname,'type',format_type(x.atttypid,x.atttypmod),
    'default',pg_get_expr(ad.adbin,ad.adrelid),'ordinal',x.attnum,'identity',x.attidentity,
    'not_null',x.attnotnull,'generated',x.attgenerated,'acl',to_jsonb(x.attacl)) ORDER BY x.attnum),'[]'::jsonb)
   INTO v FROM pg_attribute x LEFT JOIN pg_attrdef ad ON ad.adrelid=x.attrelid AND ad.adnum=x.attnum
   WHERE x.attrelid=rel AND x.attnum>0 AND NOT x.attisdropped;
  IF v IS DISTINCT FROM t->'columns' THEN
   RAISE EXCEPTION 'correction_fixture_columns_changed' USING DETAIL=t->>'name';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('name',x.conname,'type',x.contype,'validated',x.convalidated,
    'deferrable',x.condeferrable,'definition',pg_get_constraintdef(x.oid,true),
    'initially_deferred',x.condeferred) ORDER BY x.conname),'[]'::jsonb)
   INTO v FROM pg_constraint x WHERE x.conrelid=rel;
  IF v IS DISTINCT FROM t->'constraints' THEN
   RAISE EXCEPTION 'correction_fixture_constraints_changed' USING DETAIL=t->>'name';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('name',x.tgname,'type',x.tgtype,'enabled',x.tgenabled,
    'deferrable',x.tgdeferrable,'definition',pg_get_triggerdef(x.oid,true),
    'initially_deferred',x.tginitdeferred,'function_definition_md5',md5(pg_get_functiondef(x.tgfoid)))
    ORDER BY x.tgname),'[]'::jsonb) INTO v FROM pg_trigger x WHERE x.tgrelid=rel AND NOT x.tgisinternal;
  IF v IS DISTINCT FROM t->'triggers' THEN
   RAISE EXCEPTION 'correction_fixture_triggers_changed' USING DETAIL=t->>'name';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('kind',ic.relkind,'live',x.indislive,'name',ic.relname,
    'owner',pg_get_userbyid(ic.relowner),'ready',x.indisready,'valid',x.indisvalid,'unique',x.indisunique,
    'primary',x.indisprimary,'clustered',x.indisclustered,'immediate',x.indimmediate,
    'definition',pg_get_indexdef(x.indexrelid),'replica_identity',x.indisreplident,
    'nulls_not_distinct',x.indnullsnotdistinct) ORDER BY ic.relname),'[]'::jsonb)
   INTO v FROM pg_index x JOIN pg_class ic ON ic.oid=x.indexrelid WHERE x.indrelid=rel;
  IF v IS DISTINCT FROM (SELECT jsonb_agg(value ORDER BY value->>'name')
    FROM jsonb_array_elements(t->'indexes') WHERE (value->>'unique')::boolean) THEN
   RAISE EXCEPTION 'correction_fixture_index_preimage_changed' USING DETAIL=t->>'name';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('cmd',x.cmd,'qual',x.qual,'roles',to_jsonb(x.roles),
    'permissive',x.permissive,'policyname',x.policyname,'with_check',x.with_check) ORDER BY x.policyname),'[]'::jsonb)
   INTO v FROM pg_policies x WHERE x.schemaname='public' AND x.tablename=t->>'name';
  IF v IS DISTINCT FROM t->'policies' THEN
   RAISE EXCEPTION 'correction_fixture_policies_changed' USING DETAIL=t->>'name';
  END IF;
  SELECT jsonb_object_agg(actor,jsonb_build_object('table',
    (SELECT jsonb_object_agg(priv,has_table_privilege(actor,rel,priv))
     FROM unnest(ARRAY['DELETE','INSERT','SELECT','UPDATE','TRIGGER','MAINTAIN','TRUNCATE','REFERENCES']) priv),
