    RAISE EXCEPTION 'correction_fixture_index_name_preexists' USING DETAIL=ix->>'name';
   END IF;
  END LOOP;
 END LOOP;
 -- These two incident relations have a smaller actual captured index shape;
 -- preserve that exact projection rather than invent absent metadata fields.
 FOR t IN SELECT value FROM jsonb_array_elements(expected_incident_indexes) LOOP
  rel:=to_regclass(t->>'name');
  IF rel IS NULL OR NOT EXISTS(SELECT 1 FROM pg_class x WHERE x.oid=rel
    AND x.relkind::text=t->>'kind' AND pg_get_userbyid(x.relowner)=t->>'owner'
    AND x.relrowsecurity=(t->>'rls')::boolean AND x.relforcerowsecurity=(t->>'force_rls')::boolean
