   RAISE EXCEPTION 'correction_fixture_relation_acl_changed' USING DETAIL=t->>'name';
  END IF;
  SELECT jsonb_agg(jsonb_build_object('name',x.attname,'number',x.attnum,'type',format_type(x.atttypid,x.atttypmod),
    'default',pg_get_expr(ad.adbin,ad.adrelid),'identity',x.attidentity,'not_null',x.attnotnull,
    'generated',x.attgenerated,'acl',to_jsonb(x.attacl)) ORDER BY x.attnum)
   INTO v FROM pg_attribute x LEFT JOIN pg_attrdef ad ON ad.adrelid=x.attrelid AND ad.adnum=x.attnum
   WHERE x.attrelid=rel AND x.attnum>0 AND NOT x.attisdropped;
  IF v IS DISTINCT FROM t->'columns' THEN
   RAISE EXCEPTION 'correction_fixture_columns_changed' USING DETAIL=t->>'name';
  END IF;
  SELECT jsonb_agg(jsonb_build_object('name',ic.relname,'definition',pg_get_indexdef(x.indexrelid),
    'ready',x.indisready,'valid',x.indisvalid) ORDER BY ic.relname)
   INTO v FROM pg_index x JOIN pg_class ic ON ic.oid=x.indexrelid WHERE x.indrelid=rel;
  IF v IS DISTINCT FROM (SELECT jsonb_agg(value ORDER BY value->>'name')
    FROM jsonb_array_elements(t->'indexes') WHERE value->>'definition' LIKE 'CREATE UNIQUE INDEX %') THEN
   RAISE EXCEPTION 'correction_fixture_index_preimage_changed' USING DETAIL=t->>'name';
  END IF;
  FOR ix IN SELECT value FROM jsonb_array_elements(t->'indexes') WHERE value->>'definition' LIKE 'CREATE INDEX %' LOOP
   IF to_regclass('public.'||(ix->>'name')) IS NOT NULL THEN
    RAISE EXCEPTION 'correction_fixture_index_name_preexists' USING DETAIL=ix->>'name';
   END IF;
  END LOOP;
 END LOOP;
 -- All four relations passed their unchanged captured guards after the
 -- fixture identity repair, before index/default-ACL supplementation.
 -- Only source-captured DDL is used.

 FOR t IN SELECT value FROM jsonb_array_elements(expected) LOOP
  FOR ix IN SELECT value FROM jsonb_array_elements(t->'indexes') WHERE NOT(value->>'unique')::boolean LOOP
   EXECUTE ix->>'definition';
  END LOOP;
  IF jsonb_typeof(t->'options')='array' THEN
   EXECUTE format('ALTER TABLE public.%I SET (%s)',t->>'name',
    (SELECT string_agg(value,', ' ORDER BY ordinal) FROM jsonb_array_elements_text(t->'options') WITH ORDINALITY AS z(value,ordinal)));
  END IF;
 END LOOP;
 FOR t IN SELECT value FROM jsonb_array_elements(expected_incident_indexes) LOOP
  FOR ix IN SELECT value FROM jsonb_array_elements(t->'indexes') WHERE value->>'definition' LIKE 'CREATE INDEX %' LOOP
   EXECUTE ix->>'definition';
  END LOOP;
 END LOOP;
 FOR d IN SELECT value FROM jsonb_array_elements(expected_defaults) LOOP
  kind := CASE d->>'object_type' WHEN 'S' THEN 'SEQUENCES' WHEN 'f' THEN 'FUNCTIONS' WHEN 'r' THEN 'TABLES' END;
  IF kind IS NULL THEN RAISE EXCEPTION 'correction_fixture_unhandled_default_acl';END IF;
  FOR a IN SELECT value FROM jsonb_array_elements_text(d->'acl') LOOP
   recipient := split_part(a,'=',1);
   privileges := CASE split_part(split_part(a,'=',2),'/',1)
    WHEN 'rwU' THEN 'SELECT,UPDATE,USAGE'
    WHEN 'X' THEN 'EXECUTE'
    WHEN 'arwdDxtm' THEN 'INSERT,SELECT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN'
    WHEN 'arwdxtm' THEN 'INSERT,SELECT,UPDATE,DELETE,REFERENCES,TRIGGER,MAINTAIN' END;
   IF privileges IS NULL OR split_part(a,'/',2) IS DISTINCT FROM d->>'owner' THEN
    RAISE EXCEPTION 'correction_fixture_unhandled_default_acl';
   END IF;
   EXECUTE format('ALTER DEFAULT PRIVILEGES FOR ROLE %I IN SCHEMA %I GRANT %s ON %s TO %I',
    d->>'owner',d->>'schema',privileges,kind,recipient);
  END LOOP;
 END LOOP;
 -- Re-read exact supplemented attributes. Defaults in other schemas must
 -- remain byte-equivalent; public/global metadata must match the capture.
 FOR t IN SELECT value FROM jsonb_array_elements(expected) LOOP
  rel:=to_regclass('public.'||(t->>'name'));
  SELECT COALESCE(jsonb_agg(jsonb_build_object('kind',ic.relkind,'live',x.indislive,'name',ic.relname,
    'owner',pg_get_userbyid(ic.relowner),'ready',x.indisready,'valid',x.indisvalid,'unique',x.indisunique,
    'primary',x.indisprimary,'clustered',x.indisclustered,'immediate',x.indimmediate,
    'definition',pg_get_indexdef(x.indexrelid),'replica_identity',x.indisreplident,
    'nulls_not_distinct',x.indnullsnotdistinct) ORDER BY ic.relname),'[]'::jsonb)
   INTO v FROM pg_index x JOIN pg_class ic ON ic.oid=x.indexrelid WHERE x.indrelid=rel;
  IF v IS DISTINCT FROM t->'indexes' THEN
   RAISE EXCEPTION 'correction_fixture_index_readback_changed' USING DETAIL=t->>'name';
  END IF;
  SELECT to_jsonb(x.reloptions) INTO v FROM pg_class x WHERE x.oid=rel;
  IF v IS DISTINCT FROM NULLIF(t->'options','null'::jsonb) THEN
   RAISE EXCEPTION 'correction_fixture_options_readback_changed' USING DETAIL=t->>'name';
  END IF;
 END LOOP;
 FOR t IN SELECT value FROM jsonb_array_elements(expected_incident_indexes) LOOP
  rel:=to_regclass(t->>'name');
  SELECT jsonb_agg(jsonb_build_object('name',ic.relname,'definition',pg_get_indexdef(x.indexrelid),
    'ready',x.indisready,'valid',x.indisvalid) ORDER BY ic.relname)
   INTO v FROM pg_index x JOIN pg_class ic ON ic.oid=x.indexrelid WHERE x.indrelid=rel;
  IF v IS DISTINCT FROM t->'indexes' THEN
   RAISE EXCEPTION 'correction_fixture_index_readback_changed' USING DETAIL=t->>'name';
  END IF;
 END LOOP;
 SELECT jsonb_agg(jsonb_build_object('acl',(SELECT jsonb_agg(y::text ORDER BY y::text) FROM unnest(x.defaclacl) y),
   'owner',pg_get_userbyid(x.defaclrole),'schema',n.nspname,'object_type',x.defaclobjtype)
   ORDER BY pg_get_userbyid(x.defaclrole),x.defaclobjtype)
  INTO v FROM pg_default_acl x LEFT JOIN pg_namespace n ON n.oid=x.defaclnamespace
  WHERE x.defaclnamespace=0 OR x.defaclnamespace='public'::regnamespace;
 IF v IS DISTINCT FROM expected_defaults THEN RAISE EXCEPTION 'correction_fixture_default_acl_readback_changed';END IF;
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.oid),'[]'::jsonb) INTO v FROM pg_default_acl x
  WHERE x.defaclnamespace<>0 AND x.defaclnamespace<>'public'::regnamespace;
 IF v IS DISTINCT FROM before_other_defaults THEN RAISE EXCEPTION 'correction_fixture_unrelated_defaults_changed';END IF;
END;
$bootstrap$;
COMMIT;
